// @name JSX: To-do
// @background #f1f5f9
// @refresh 3600
// A to-do list you can tap: a row ticks itself off and the header counts.
const items = [
  'Water the plants',
  'Call grandma about Sunday',
  'Book the dentist',
  'Oat milk, coffee beans, lemons',
  'Take the recycling out',
  'Fix the bike light',
]

let done = null
const load = () => {
  if (done === null) done = frameos.recall('done') ?? [true, false, false, false, false, false]
}

const Check = () => (
  <svg className="w-5 h-5 text-white" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth={3} strokeLinecap="round" strokeLinejoin="round">
    <path d="M5 12l5 5L20 7" />
  </svg>
)

export function get(app) {
  load()
  const count = done.filter(Boolean).length
  return (
    <div className="flex flex-col gap-2 p-6 bg-slate-100 text-slate-800">
      <div className="flex items-end justify-between">
        <span className="text-4xl font-bold">Today</span>
        <span className="text-lg text-slate-500">{`${count} of ${items.length} done`}</span>
      </div>
      <div className="h-2 rounded-full bg-slate-200 mb-2">
        <div className={`h-2 rounded-full bg-emerald-500 w-[${(count * 100) / items.length}%]`} />
      </div>
      {items.map((text, i) => (
        <div className="flex items-center gap-4 rounded-2xl bg-white px-4 py-3 active:bg-sky-100"
          onClick={() => { done[i] = !done[i]; frameos.remember('done', done) }}>
          <div className={`w-7 h-7 rounded-full flex items-center justify-center ${done[i] ? 'bg-emerald-500' : 'border-2 border-slate-300'}`}>
            {done[i] ? <Check /> : null}
          </div>
          <span className={`flex-1 text-lg truncate ${done[i] ? 'line-through text-slate-400' : ''}`}>{text}</span>
        </div>
      ))}
    </div>
  )
}
